const finalizarPicking = async () => {
  if (finalizando) return; // Guard local contra duplo-clique
  if (!requisicaoId) return;

  const itensNaoColetados = itens.filter(
    (item) => !(String(item.quantidade_enviada || '').trim() !== ''),
  );
  if (itensNaoColetados.length > 0) {
    toast({
      title: 'Atenção',
      description: `Ainda há ${itensNaoColetados.length} itens não coletados.`,
      variant: 'destructive',
    });
    return;
