/**
 * Testes co-located: integração dar_saida_requisicao em finalizarComSaida/finalizarSemSaida
 *
 * Cobre:
 *  1. RPC dar_saida_requisicao é chamada após transição de status bem-sucedida (com saída).
 *  2. alertas não-vazios disparam toast de warning (destructive).
 *  3. Falha na RPC reverte status para em_progresso e NÃO navega.
 *  4. "Finalizar" (sem saída) NÃO chama o RPC e navega para /logistica.
 *  5. Aviso de não-bipados aparece quando há item marcado sem bip.
 */
import {
  render,
  screen,
  waitFor,
  act,
  fireEvent,
} from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import PaginaPicking from './PaginaPicking.page';
import { BrowserRouter } from 'react-router-dom';
import * as routerDom from 'react-router-dom';
import { supabase } from '@/integrations/supabase/client';

// ── mocks de módulos ────────────────────────────────────────────────────────

// SaidaRequisicaoResumoDialog faz queries próprias ao Supabase; isolamos com stub.
vi.mock('./SaidaRequisicaoResumoDialog', () => ({
  SaidaRequisicaoResumoDialog: ({ open, onClose }: { open: boolean; onClose: () => void }) =>
    open ? (
      <div data-testid="resumo-saida-dialog">
        <button onClick={onClose}>Fechar</button>
      </div>
    ) : null,
}));

vi.mock('react-router-dom', async () => {
  const actual = await vi.importActual('react-router-dom');
  return {
    ...(actual as Record<string, unknown>),
    useParams: vi.fn(),
    useNavigate: vi.fn(),
  };
});

vi.mock('@/shared/hooks/useAuth', () => ({
  useAuth: () => ({
    user: { id: 'mock-user-id', user_metadata: { full_name: 'Operador Teste' } },
    userProfile: { nome: 'Operador Teste' },
  }),
}));

vi.mock('@/shared/hooks/usePermissions', () => ({
  usePermissions: () => ({
    canViewRequisicao: () => true,
    canEditRequisicao: () => true,
  }),
}));

vi.mock('@/shared/contexts/StoreContext', () => ({
  useStore: () => ({ stores: [] }),
}));

vi.mock('@/shared/hooks/use-mobile', () => ({
  useIsMobile: () => false,
  useIsTablet: () => false,
}));

vi.mock('@/shared/lib/expedition-log-service', () => ({
  logExpeditionEvent: vi.fn().mockResolvedValue(undefined),
  logSeparationCompleted: vi.fn().mockResolvedValue(undefined),
}));

// Toast mock: precisamos espioná-lo para verificar chamadas.
const mockToast = vi.fn();
vi.mock('@/shared/hooks/use-toast', () => ({
  useToast: () => ({ toast: mockToast }),
}));

// Supabase é re-mockado aqui em nível de teste (sobrescreve o global de setup.ts)
vi.mock('@/integrations/supabase/client', () => ({
  supabase: {
    from: vi.fn(),
    channel: vi.fn(),
    removeChannel: vi.fn().mockResolvedValue(undefined),
    rpc: vi.fn(),
    auth: {
      getUser: vi
        .fn()
        .mockResolvedValue({ data: { user: { id: 'mock-user-id' } }, error: null }),
    },
  },
}));

class StubResizeObserver {
  observe() {}
  unobserve() {}
  disconnect() {}
}
window.ResizeObserver = StubResizeObserver;
Element.prototype.scrollIntoView = vi.fn();

// ── helpers de mock ─────────────────────────────────────────────────────────

const mockNavigate = vi.fn();

const mockChannel = {
  on: vi.fn().mockReturnThis(),
  subscribe: vi.fn((cb?: (status: string) => void) => {
    if (typeof cb === 'function') cb('SUBSCRIBED');
    return mockChannel;
  }),
  track: vi.fn(),
  untrack: vi.fn(),
  send: vi.fn(),
  unsubscribe: vi.fn(),
  presenceState: vi.fn(() => ({})),
};

const mockReqInfo = {
  id: 123,
  nome: 'Req #123',
  solicitante: 'Ana',
  loja_solicitante: 'Asa Sul',
  loja_preparadora: 'Fábrica',
  data_pedido: '2026-06-01',
  data_recebimento: null,
  subtitle: null,
};

// Itens com quantidade_enviada preenchida — permite que os botões Finalizar sejam habilitados.
const mockItensColetados = [
  {
    id: 10,
    nome_produto: 'Brownie',
    quantidade_solicitada: 5,
    quantidade_enviada: '5',
    observacao: '',
    category: 'Geral',
    ordem: 1,
    lote: '',
    validade: '',
    produto_id: null,
  },
];

const makeChainable = (table: string) => {
  const c: Record<string, ReturnType<typeof vi.fn> | ((resolve: (v: { data: unknown; error: null }) => void) => unknown)> = {
    select: vi.fn(() => c),
    eq: vi.fn(() => c),
    order: vi.fn(() => c),
    limit: vi.fn(() => c),
    in: vi.fn(() => c),
    not: vi.fn(() => c),
    ilike: vi.fn(() => c),
    or: vi.fn(() => c),
    gt: vi.fn(() => c),
    gte: vi.fn(() => c),
    lte: vi.fn(() => c),
    update: vi.fn(() => c),
    insert: vi.fn(() => c),
    delete: vi.fn(() => c),
    maybeSingle: vi.fn(() => Promise.resolve({ data: null, error: null })),
    single: vi.fn(() =>
      Promise.resolve({
        data: table === 'requisicoes' ? mockReqInfo : mockItensColetados[0],
        error: null,
      }),
    ),
    then: (resolve: (v: { data: unknown; error: null }) => void) => {
      if (table === 'requisicoes')
        return resolve({ data: mockReqInfo, error: null });
      if (table === 'requisicoes_itens')
        return resolve({ data: mockItensColetados, error: null });
      if (table === 'profiles')
        return resolve({
          data: { nome: 'Operador Teste', username: 'operador' },
          error: null,
        });
      // etiquetas_qr_eventos e etiquetas_qr: por padrão retornam lista vazia
      // (nenhum bip) — o item Brownie (produto_id: null, masterId indefinido)
      // seria detectado como não-bipado. Isso dispara o dialog de aviso.
      return resolve({ data: [], error: null });
    },
  };
  return c;
};

/** Configura supabase.from + channel + rpc conforme cenário. */
const setupSupabaseMock = ({
  rpcResult,
  etiquetasQrEventos = [],
  etiquetasQr = [],
}: {
  rpcResult: { data: unknown; error: null | { message: string } };
  etiquetasQrEventos?: unknown[];
  etiquetasQr?: unknown[];
}) => {
  (supabase.from as ReturnType<typeof vi.fn>).mockImplementation((table: string) => {
    const c = makeChainable(table);
    // UPDATE atômico de status: retornar 1 row para simular sucesso de reserva.
    if (table === 'requisicoes') {
      c.update = vi.fn(() => {
        const upChain = { ...c };
        upChain.eq = vi.fn(() => upChain);
        upChain.select = vi.fn(() =>
          Promise.resolve({ data: [{ id: 123 }], error: null }),
        );
        return upChain;
      });
    }
    if (table === 'etiquetas_qr_eventos') {
      // Precisa resolver via .then() mas a chain usa .in() que retorna a chain
      // O then() será chamado pela promise implícita
      const eventos = etiquetasQrEventos;
      const qrEvChain = {
        ...c,
        then: (resolve: (v: { data: unknown; error: null }) => void) =>
          resolve({ data: eventos, error: null }),
      };
      qrEvChain.select = vi.fn(() => qrEvChain);
      qrEvChain.eq = vi.fn(() => qrEvChain);
      qrEvChain.in = vi.fn(() =>
        Promise.resolve({ data: eventos, error: null }),
      );
      return qrEvChain;
    }
    if (table === 'etiquetas_qr') {
      const tags = etiquetasQr;
      const qrChain = {
        ...c,
        then: (resolve: (v: { data: unknown; error: null }) => void) =>
          resolve({ data: tags, error: null }),
      };
      qrChain.select = vi.fn(() => qrChain);
      qrChain.in = vi.fn(() =>
        Promise.resolve({ data: tags, error: null }),
      );
      return qrChain;
    }
    return c;
  });
  (supabase.channel as ReturnType<typeof vi.fn>).mockReturnValue(mockChannel);
  (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValue(rpcResult);
};

const renderComponent = () =>
  render(
    <BrowserRouter>
      <PaginaPicking />
    </BrowserRouter>,
  );

/** Aguarda o carregamento inicial do componente. */
const waitForLoad = () =>
  waitFor(() => expect(screen.getByText('Brownie')).toBeInTheDocument(), {
    timeout: 5000,
  });

/**
 * Clica em "Finalizar e dar saída".
 * Se o dialog de aviso de não-bipados aparecer, clica em "Dar saída só dos bipados"
 * para que o fluxo do RPC seja exercitado nos testes existentes.
 */
const clickFinalizarComSaida = async () => {
  const btn = screen.getByRole('button', { name: /finalizar e dar sa[ií]da/i });
  await act(async () => {
    fireEvent.click(btn);
  });
  // Se o dialog de aviso aparecer (itens sem bip), confirmar para prosseguir ao RPC
  const confirmarBtn = screen.queryByRole('button', { name: /dar sa[ií]da s[oó] dos bipados/i });
  if (confirmarBtn) {
    await act(async () => {
      fireEvent.click(confirmarBtn);
    });
  }
};

// ── suíte ───────────────────────────────────────────────────────────────────

describe('finalizarPicking() — integração dar_saida_requisicao', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    (routerDom.useParams as ReturnType<typeof vi.fn>).mockReturnValue({ requisicaoId: '123' });
    (routerDom.useNavigate as ReturnType<typeof vi.fn>).mockReturnValue(mockNavigate);
  });

  it('1. chama dar_saida_requisicao e abre dialog de resumo (navigate NÃO é chamado imediatamente)', async () => {
    setupSupabaseMock({
      rpcResult: {
        data: { ok: true, requisicao_id: 123, etiquetas_processadas: 3, total_quantidade: 9, ja_processadas: 0, alertas: [] },
        error: null,
      },
    });

    renderComponent();
    await waitForLoad();
    await clickFinalizarComSaida();

    // RPC deve ter sido chamada com o id correto
    await waitFor(() => {
      expect(supabase.rpc).toHaveBeenCalledWith('dar_saida_requisicao', {
        p_requisicao_id: 123,
      });
    });

    // Dialog de resumo deve abrir em vez de navegar imediatamente
    await waitFor(() => {
      expect(screen.getByTestId('resumo-saida-dialog')).toBeInTheDocument();
    });

    // navigate NÃO deve ter sido chamado ainda (só acontece ao fechar o dialog)
    expect(mockNavigate).not.toHaveBeenCalledWith('/logistica');
  });

  it('2. exibe toast de warning quando alertas é não-vazio', async () => {
    setupSupabaseMock({
      rpcResult: {
        data: {
          ok: true,
          requisicao_id: 123,
          etiquetas_processadas: 2,
          total_quantidade: 4,
          ja_processadas: 0,
          alertas: [{ uid: 'abc', motivo: 'saldo_insuficiente' }],
        },
        error: null,
      },
    });

    renderComponent();
    await waitForLoad();
    await clickFinalizarComSaida();

    await waitFor(() => {
      // Deve ter chamado toast de sucesso E toast de warning (destructive)
      const toastCalls = mockToast.mock.calls;
      const warningCall = toastCalls.find(
        ([arg]: [{ variant?: string; title?: string; description?: string }]) =>
          arg?.variant === 'destructive' && /saldo insuficiente/i.test(arg?.description ?? ''),
      );
      expect(warningCall).toBeDefined();
    });
  });

  it('3. quando RPC falha, status reverte para em_progresso e navigate NÃO é chamado', async () => {
    setupSupabaseMock({
      rpcResult: {
        data: null,
        error: { message: 'connection timeout' },
      },
    });

    renderComponent();
    await waitForLoad();
    await clickFinalizarComSaida();

    await waitFor(() => {
      // navigate('/logistica') NÃO deve ter sido chamado
      expect(mockNavigate).not.toHaveBeenCalledWith('/logistica');
    });

    // O UPDATE de rollback (em_progresso) deve ter sido tentado
    await waitFor(() => {
      // supabase.from('requisicoes').update() é chamado duas vezes:
      //   1ª: reserva → status='finalizada'
      //   2ª: rollback → status='em_progresso'
      const fromCalls = (supabase.from as ReturnType<typeof vi.fn>).mock.calls;
      const reqCalls = fromCalls.filter((args) => args[0] === 'requisicoes');
      expect(reqCalls.length).toBeGreaterThanOrEqual(2);
    });
  });

  it('4. "Finalizar" (sem saída) NÃO chama o RPC e navega para /logistica', async () => {
    setupSupabaseMock({
      rpcResult: { data: null, error: null },
    });

    renderComponent();
    await waitForLoad();

    // Clica exatamente no botão "Finalizar" (não o "Finalizar e dar saída")
    const btn = screen.getByRole('button', { name: /^finalizar$/i });
    await act(async () => {
      fireEvent.click(btn);
    });

    await waitFor(() => {
      // RPC NÃO deve ter sido chamada
      expect(supabase.rpc).not.toHaveBeenCalledWith('dar_saida_requisicao', expect.anything());
    });

    await waitFor(() => {
      // Deve navegar para /logistica
      expect(mockNavigate).toHaveBeenCalledWith('/logistica');
    });
  });

  it('5. aviso de não-bipados aparece quando há item marcado sem bip; RPC só roda após confirmar', async () => {
    // etiquetas_qr_eventos vazio = nenhum bip → Brownie (sem masterId) será não-bipado
    setupSupabaseMock({
      rpcResult: {
        data: { ok: true, requisicao_id: 123, etiquetas_processadas: 0, total_quantidade: 0, ja_processadas: 0, alertas: [] },
        error: null,
      },
      etiquetasQrEventos: [],
      etiquetasQr: [],
    });

    renderComponent();
    await waitForLoad();

    // Clica em "Finalizar e dar saída"
    const btnComSaida = screen.getByRole('button', { name: /finalizar e dar sa[ií]da/i });
    await act(async () => {
      fireEvent.click(btnComSaida);
    });

    // O dialog de aviso deve aparecer
    await waitFor(() => {
      expect(screen.getByText(/itens n[aã]o bipados n[aã]o v[aã]o dar baixa/i)).toBeInTheDocument();
    });

    // O RPC NÃO deve ter sido chamado enquanto o dialog está aberto
    expect(supabase.rpc).not.toHaveBeenCalledWith('dar_saida_requisicao', expect.anything());

    // Clicar em "Dar saída só dos bipados" — dispara executarFinalizacaoComSaida
    const confirmar = screen.getByRole('button', { name: /dar sa[ií]da s[oó] dos bipados/i });
    await act(async () => {
      fireEvent.click(confirmar);
    });

    // Agora o RPC deve ser chamado
    await waitFor(() => {
      expect(supabase.rpc).toHaveBeenCalledWith('dar_saida_requisicao', {
        p_requisicao_id: 123,
      });
    });
  });
});

