      },
      etiquetasQrEventos: [],
      etiquetasQr: [],
    });

    renderComponent();
    await waitForLoad();

    // Clica em "Finalizar e dar saída"
    const btnComSaida = screen.getByRole('button', { name: /finalizar e dar sa[ií]da/i });
    await act(async () => {
      fireEvent.click(btnComSaida);
    });

    // O dialog de aviso deve aparecer
    await waitFor(() => {
      expect(screen.getByText(/itens n[aã]o bipados n[aã]o v[aã]o dar baixa/i)).toBeInTheDocument();
    });

    // O RPC NÃO deve ter sido chamado enquanto o dialog está aberto
    expect(supabase.rpc).not.toHaveBeenCalledWith('dar_saida_requisicao', expect.anything());

    // Clicar em "Dar saída só dos bipados" — dispara executarFinalizacaoComSaida
    const confirmar = screen.getByRole('button', { name: /dar sa[ií]da s[oó] dos bipados/i });
    await act(async () => {
      fireEvent.click(confirmar);
    });

    // Agora o RPC deve ser chamado
    await waitFor(() => {
      expect(supabase.rpc).toHaveBeenCalledWith('dar_saida_requisicao', {
        p_requisicao_id: 123,
      });
    });
  });
});

